-- Gaps, borders, layouts and misc

-- Dynamic colors generated by Wallust (~/.config/hypr/conf/colors.lua, not versioned).
-- Loaded by absolute path: Hyprland resolves the Stow symlink, so require()
-- searches ~/dotfiles/.config/hypr/ and would never find the generated file.
-- Fall back to a neutral palette if Wallust hasn't run yet (e.g. fresh clone).
local ok, colors = pcall(dofile, os.getenv("HOME") .. "/.config/hypr/conf/colors.lua")
if not ok then
    hl.notification.create({ text = "colors.lua not found, using fallback palette", timeout = 8000 })
    colors = {
        background = "rgb(161616)",
        color4     = "rgb(4A5B8F)",
        color5     = "rgb(5569A7)",
    }
end

hl.config({
    general = {
        gaps_in     = 5,
        gaps_out    = 10,
        border_size = 2,

        col = {
            active_border   = { colors = { colors.color4, colors.color5 }, angle = 45 },
            inactive_border = colors.background,
        },

        resize_on_border = false,
        allow_tearing    = false,
        layout           = "dwindle",
    },

    dwindle = {
        preserve_split = true,
    },

    master = {
        new_status = "master",
    },

    misc = {
        force_default_wallpaper = -1,
        disable_hyprland_logo   = false,
    },
})
